package com.megacomanda.vistas;
import com.megacomanda.modelo.*;import com.megacomanda.servicios.GestorPedidos;import javax.swing.*;import javax.swing.table.DefaultTableModel;import javax.swing.border.EmptyBorder;import java.awt.*;import java.util.LinkedHashSet;import java.util.Set;
public class VistaRegistroPedido extends JPanel {
 private final GestorPedidos gestor;private final JComboBox<Mesa> mesas;private final JComboBox<String> categorias;private final JComboBox<Producto> productos;private final JSpinner cantidad=new JSpinner(new SpinnerNumberModel(1,1,50,1));private final JTextField observacion=new JTextField(20);private final DefaultTableModel modelo=new DefaultTableModel(new String[]{"Producto","Cantidad","Observación","Subtotal"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable tabla=new JTable(modelo);private Pedido borrador;private final JLabel total=new JLabel("$0");
 public VistaRegistroPedido(GestorPedidos gestor){super(new BorderLayout(14,14));this.gestor=gestor;setBackground(Estilo.FONDO);setBorder(new EmptyBorder(20,22,20,22));
  mesas=new JComboBox<>(gestor.getMesas().toArray(Mesa[]::new));Set<String> cats=new LinkedHashSet<>();for(Producto p:gestor.getMenu())cats.add(p.getCategoria());categorias=new JComboBox<>(cats.toArray(String[]::new));productos=new JComboBox<>();actualizarProductos();categorias.addActionListener(e->actualizarProductos());
  JPanel top=new JPanel(new BorderLayout(8,8));top.setOpaque(false);top.add(Estilo.encabezado("Nueva comanda","Selecciona la mesa, agrega productos y envía la orden directamente a cocina."),BorderLayout.NORTH);
  JPanel form=Estilo.tarjeta();form.setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(5,6,5,6);c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;
  campo(form,c,0,"MESA",mesas);campo(form,c,1,"CATEGORÍA",categorias);campo(form,c,2,"PRODUCTO",productos);campo(form,c,3,"CANTIDAD",cantidad);campo(form,c,4,"OBSERVACIONES",observacion);
  JButton agregar=Estilo.boton("+ Agregar producto",true);agregar.addActionListener(e->agregar());c.gridx=5;c.gridy=1;c.weightx=0;form.add(agregar,c);top.add(form,BorderLayout.CENTER);add(top,BorderLayout.NORTH);
  Estilo.tabla(tabla);JPanel centro=Estilo.tarjeta();centro.add(Estilo.subtitulo("DETALLE DE LA COMANDA"),BorderLayout.NORTH);centro.add(Estilo.scroll(tabla),BorderLayout.CENTER);JButton quitar=Estilo.boton("Quitar último",false);quitar.addActionListener(e->quitar());JPanel acciones=new JPanel(new FlowLayout(FlowLayout.LEFT));acciones.setOpaque(false);acciones.add(quitar);centro.add(acciones,BorderLayout.SOUTH);add(centro,BorderLayout.CENTER);
  JPanel pie=Estilo.tarjeta();pie.setLayout(new BorderLayout());JPanel totalBox=new JPanel(new GridLayout(2,1));totalBox.setOpaque(false);totalBox.add(Estilo.subtitulo("TOTAL DE LA COMANDA"));total.setFont(new Font("SansSerif",Font.BOLD,25));total.setForeground(Estilo.NARANJA);totalBox.add(total);pie.add(totalBox,BorderLayout.WEST);JButton enviar=Estilo.boton("Enviar a cocina  →",true);enviar.addActionListener(e->enviar());pie.add(enviar,BorderLayout.EAST);add(pie,BorderLayout.SOUTH);
 }
 private void campo(JPanel p,GridBagConstraints c,int x,String label,JComponent comp){JPanel box=new JPanel(new BorderLayout(3,5));box.setOpaque(false);JLabel l=Estilo.subtitulo(label);l.setFont(new Font("SansSerif",Font.BOLD,10));box.add(l,BorderLayout.NORTH);comp.setFont(new Font("SansSerif",Font.PLAIN,12));box.add(comp,BorderLayout.CENTER);c.gridx=x;c.gridy=0;c.weightx=1;p.add(box,c);}
 private void actualizarProductos(){if(productos==null||categorias==null)return;productos.removeAllItems();String cat=(String)categorias.getSelectedItem();for(Producto p:gestor.getMenu())if(p.getCategoria().equals(cat))productos.addItem(p);}
 private void asegurarBorrador(){if(borrador==null)borrador=gestor.crearPedido((Mesa)mesas.getSelectedItem());}
 private void agregar(){try{asegurarBorrador();Producto p=(Producto)productos.getSelectedItem();int n=(Integer)cantidad.getValue();gestor.agregarItem(borrador,p,n,observacion.getText());modelo.addRow(new Object[]{p.getNombre(),n,observacion.getText(),String.format("$%,.0f",p.getPrecio()*n)});actualizarTotal();observacion.setText("");}catch(RuntimeException ex){aviso(ex.getMessage());}}
 private void quitar(){if(borrador==null||borrador.getItems().isEmpty())return;borrador.eliminarUltimoItem();modelo.removeRow(modelo.getRowCount()-1);actualizarTotal();}
 private void actualizarTotal(){total.setText(String.format("$%,.0f",borrador==null?0:borrador.getTotal()));}
 private void enviar(){if(borrador==null||borrador.getItems().isEmpty()){aviso("Agrega al menos un producto antes de enviar.");return;}try{gestor.enviarPedido(borrador);aviso("La comanda fue enviada a cocina correctamente.");borrador=null;modelo.setRowCount(0);actualizarTotal();}catch(RuntimeException ex){aviso(ex.getMessage());}}
 private void aviso(String s){JOptionPane.showMessageDialog(this,s,"MegaComanda",JOptionPane.INFORMATION_MESSAGE);}
}
